attempted=[j for j in jobs if j.get('attempts') and j['status']!='cached_verified'];actual=[j for j in jobs if j['status']=='verified'];cached=[j for j in jobs if j['status']=='cached_verified'];first=[j for j in actual if j['seed']==20260919];extra=[j for j in actual if j['seed']!=20260919]
